const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for San Juan, Puerto Rico
  var sanJuan = ee.Geometry.Point([-66.1057, 18.4663]).buffer(5000); // 5km buffer around city center

  // 2. Define date ranges for the two periods (3-day windows to capture the specific nights)
  var period1_start = '2017-09-01';
  var period1_end = '2017-09-03'; // Captures night of Sep 1-2 (image for Sep 2)
  var period2_start = '2017-09-27';
  var period2_end = '2017-09-29'; // Captures night of Sep 27-28 (image for Sep 28)

  // Function to process a date range and return mean brightness and pixel count
  function processPeriod(startDate, endDate, label) {
    var col = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
                .filterDate(startDate, endDate)
                .filterBounds(sanJuan);

    var size = col.size();
    var count = size.getInfo();
    print(label + ' Images:', count);

    if (count === 0) {
      return {mean: null, pixelCount: 0, hasData: false};
    }

    // Composite the images by median
    var composite = col.median();

    // Cloud masking: QF_Cloud_Mask bits 0-1: 00=clear, 01=probably clear, 10=probably cloudy, 11=cloudy
    // We keep only clear and probably clear (00 and 01)
    var cloudMask = composite.select('QF_Cloud_Mask').bitwiseAnd(3).lte(1);
    var masked = composite.select('Gap_Filled_DNB_BRDF-Corrected_NTL').updateMask(cloudMask);

    // Compute mean and pixel count over the region
    var reduction = masked.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sanJuan,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });

    var mean = reduction.get('Gap_Filled_DNB_BRDF-Corrected_NTL');
    var pixelCount = reduction.get('Gap_Filled_DNB_BRDF-Corrected_NTL_count');

    return {mean: mean, pixelCount: pixelCount, hasData: true};
  }

  // Process both periods
  var result1 = processPeriod(period1_start, period1_end, 'Sep 1-2, 2017');
  var result2 = processPeriod(period2_start, period2_end, 'Sep 27-28, 2017');

  // Check for no data
  if (!result1.hasData || !result2.hasData) {
    print('One or both periods have no images.');
    print('<answer>C1</answer>');
    return;
  }

  // Get the values
  var mean1 = result1.mean.getInfo();
  var mean2 = result2.mean.getInfo();
  var count1 = result1.pixelCount.getInfo();
  var count2 = result2.pixelCount.getInfo();

  print('Sep 1-2 mean brightness:', mean1, 'Valid pixels:', count1);
  print('Sep 27-28 mean brightness:', mean2, 'Valid pixels:', count2);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    print('No valid pixels after masking.');
    print('<answer>C2</answer>');
    return;
  }

  // Validate the mean values
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < 0 || mean2 < 0 || mean1 > 200 || mean2 > 200) { // Rough range for nighttime lights radiance
    print('Invalid brightness values.');
    print('<answer>C3</answer>');
    return;
  }

  // Compare: is brightness on Sep 27-28 lower than Sep 1-2?
  if (mean2 < mean1) {
    print('Yes, nighttime brightness was lower on Sep 27-28.');
    print('<answer>A</answer>');
  } else {
    print('No, nighttime brightness was not lower on Sep 27-28.');
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
